if self.query.combinator:
    src = resolved.get_source_expressions()[0]
    # Relabel order by columns to raw numbers if this is a combined
    # query; necessary since the columns can't be referenced by the
    # fully qualified name and the simple column names may collide.
    for idx, (sel_expr, _, col_alias) in enumerate(self.select):
        if is_ref and col_alias == src.refs:
            src = src.source
        elif col_alias:
            continue
        if src == sel_expr:
            resolved.set_source_expressions([RawSQL('%d' % (idx + 1), ())])
            break
    else:
        # The ordering column may have been removed from the
        # outer select by values()/values_list() but still be
        # present in the underlying combined queries.  Search
        # the first combined query's select to find its true
        # position in the UNION output.
        found = False
        for cq in self.query.combined_queries:
            if cq.default_cols:
                # The combined query selects all model columns;
                # find src among the model's concrete fields.
                opts = cq.get_meta()
                initial_alias = cq.get_initial_alias()
                for pos, field in enumerate(opts.concrete_fields):
                    col = field.get_col(initial_alias)
                    if col == src:
                        resolved.set_source_expressions(
                            [RawSQL('%d' % (pos + 1), ())]
                        )
                        found = True
                        break
                if found:
                    break
            elif src in cq.select:
                resolved.set_source_expressions(
                    [RawSQL('%d' % (cq.select.index(src) + 1), ())]
                )
                found = True
                break
        if not found:
            raise DatabaseError(
                'ORDER BY term does not match any column in the '
                'result set.'
            )

